WITH src AS (SELECT * FROM transactions WHERE txn_type = 'DEBIT' AND NOT is_flagged), summary AS (SELECT CASE WHEN YEAR(txn_time) < 2024 THEN 'before_2024' WHEN YEAR(txn_time) = 2024 THEN '2024' ELSE 'after_2024' END AS txn_cohort, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(merchant))) AS merchant_values, SUM(amount) AS total_amount FROM src GROUP BY CASE WHEN YEAR(txn_time) < 2024 THEN 'before_2024' WHEN YEAR(txn_time) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT txn_cohort, merchant_values FROM summary
